  "headline": "Rivaroxaban is not on FDA's shortage list; three sites hold 12.6 to 22.6 days on hand",
  "headline_cites": ["D4", "D1", "D2", "D3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows rivaroxaban is not listed as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East holds 147 tablets of the 15 mg presentation at 9.7 tablets per day, providing 15.2 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 218 tablets at the same daily use, providing 22.6 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale Lakeside holds 28 tablets at 2.2 tablets per day, providing 12.6 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "The rule ranks Alembic Pharmaceuticals Limited as the first alternate manufacturer to buy from, noting it is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D5"]
    },
    {
      "text": "Alembic Pharmaceuticals Limited (FEI 3004956904) received a NAI classification on its most recent inspection dated 2024-07-26.",
      "cites": ["E9"]
    },
    {
      "text": "FDA's shortage list includes a Janssen Pharmaceuticals rivaroxaban for suspension product marked To Be Discontinued with an initial posting date of 2026-09-18.",
      "cites": ["E10"]
    }
  ]
